<template>
  <div id="app">
    <button class="download-btn" @click="downloadPDF">PDF 다운로드</button>
    <div id="fullPage">
      <Header />
      <main class="container">
        <Profile />
        <Skills />
        <Projects />
        <About />
        <ThankYou />
      </main>
      <Footer />
    </div>
  </div>
</template>

<script>
import Header from "./components/PageHeader.vue";
import Profile from "./components/MyProfile.vue";
import Projects from "./components/MyProjects.vue";
import About from "./components/AboutMe.vue";
import ThankYou from "./components/ThankYou.vue";
import Footer from "./components/PageFooter.vue";
import Skills from "./components/MySkills.vue";

import html2canvas from "html2canvas";
import jsPDF from "jspdf";

export default {
  name: "App",
  components: {
    Header,
    Profile,
    Skills,
    Projects,
    About,
    ThankYou,
    Footer,
  },
  methods: {
    async downloadPDF() {
      const page = document.getElementById("fullPage");
      page.classList.add("print-mode");

      await new Promise((resolve) => setTimeout(resolve, 500));

      try {
        const canvas = await html2canvas(page, {
          scale: 2,
          useCORS: true,
          logging: false,
          backgroundColor: "#ffffff",
          windowHeight: page.scrollHeight,
        });

        const imgData = canvas.toDataURL("image/png");
        const pdf = new jsPDF("p", "mm", "a4");
        const pdfWidth = 210;
        const pdfHeight = 297;
        const imgWidth = canvas.width;
        const imgHeight = canvas.height;
        const ratio = Math.min(pdfWidth / imgWidth, pdfHeight / imgHeight);
        const imgX = (pdfWidth - imgWidth * ratio) / 2;
        const imgY = 0;

        pdf.addImage(
          imgData,
          "PNG",
          imgX,
          imgY,
          imgWidth * ratio,
          imgHeight * ratio
        );

        pdf.save("Portfolio.pdf");
      } catch (error) {
        console.error("PDF 생성 오류:", error);
        alert("PDF 생성 중 오류가 발생했습니다.");
      } finally {
        page.classList.remove("print-mode");
      }
    },
  },
};
</script>

