<template>
  <header>
    <div class="container">
      <div class="header-tabs">
        <span class="tab" :class="{ active: activeTab === 'profile' }" @click="scrollTo('profile')">소개</span>
        <span class="tab-divider">|</span>
        <span class="tab" :class="{ active: activeTab === 'skills' }" @click="scrollTo('skills')">스킬</span>
        <span class="tab-divider">|</span>
        <span class="tab" :class="{ active: activeTab === 'projects' }" @click="scrollTo('projects')">프로젝트</span>
        <span class="tab-divider">|</span>
        <span class="tab" :class="{ active: activeTab === 'about' }" @click="scrollTo('about')">이력서</span>
      </div>
    </div>
  </header>
</template>

<script>
import { ref, onMounted, onBeforeUnmount } from 'vue'

export default {
  name: 'PageHeader',
  setup() {
    const activeTab = ref('profile')

    const scrollTo = (section) => {
      const element = document.getElementById(section)
      if (element) {
        element.scrollIntoView({ 
          behavior: 'smooth',
          block: 'start'
        })
      }
    }

    const handleScroll = () => {
      const sections = ['profile', 'skills', 'projects', 'about']
      const scrollPosition = window.scrollY + 200

      for (const section of sections) {
        const element = document.getElementById(section)
        if (element) {
          const offsetTop = element.offsetTop
          const offsetBottom = offsetTop + element.offsetHeight

          if (scrollPosition >= offsetTop && scrollPosition < offsetBottom) {
            activeTab.value = section
            break
          }
        }
      }
    }

    onMounted(() => {
      window.addEventListener('scroll', handleScroll)
    })

    onBeforeUnmount(() => {
      window.removeEventListener('scroll', handleScroll)
    })

    return {
      activeTab,
      scrollTo
    }
  }
}
</script>

<style scoped>
header {
  border-bottom: 2px solid #000;
  padding: 30px 0;
  margin-bottom: 20px;
}

.header-tabs {
  display: flex;
  align-items: center;
  gap: 15px;
  font-size: 1.8rem;
  font-weight: 600;
}

.tab {
  cursor: pointer;
  transition: color 0.3s ease;
  color: #999;
}

.tab:hover {
  color: #000;
}

.tab.active {
  color: #000;
}

.tab-divider {
  color: #999;
  user-select: none;
}

@media (max-width: 768px) {
  .header-tabs {
    font-size: 1.2rem;
    gap: 10px;
  }
}
</style>
