<template>
  <section id="about" class="section" ref="sectionRef">
    <h2 class="section-title">이력서</h2>

    <div class="resume-container">
      <img :src="resumeImg" alt="이력서 이미지" class="resume-img" />
    </div>
  </section>
</template>


<script>
import { ref, onMounted, onBeforeUnmount } from "vue";

export default {
  name: "AboutMe",
  setup() {
    const sectionRef = ref(null);

    // Vue3 / Vite에서 이미지 경로 사용
    const resumeImg = new URL('@/assets/CoverLetter.png', import.meta.url).href;

    let observer = null;

    onMounted(() => {
      observer = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting)
            entry.target.classList.add("visible");
          else
            entry.target.classList.remove("visible");
        });
      });

      if (sectionRef.value) observer.observe(sectionRef.value);
    });

    onBeforeUnmount(() => {
      if (observer && sectionRef.value) observer.unobserve(sectionRef.value);
    });

    return { sectionRef, resumeImg };
  },
};
</script>


<style scoped>
.resume-container {
  width: 100%;
  max-width: 900px;
  margin: 30px auto 0;
  border: 2px solid #000;
  border-radius: 12px;
  overflow: hidden;
}

/* 이미지가 박스 안에 예쁘게 들어가도록 */
.resume-img {
  width: 100%;
  display: block;
  object-fit: cover;
}

</style>