<template>
  <section id="projects" class="section" ref="sectionRef">
    <h2 class="section-title">프로젝트</h2>
    <div class="projects-grid">
      <div
        v-for="(project, index) in projects"
        :key="index"
        class="project-card"
      >
        <div class="card-inner">
          <div class="card-front">
            <img
              :src="project.image"
              :alt="project.title"
              class="project-image"
            />
          </div>
          <div class="card-back">
            <h3 class="card-title">{{ project.title }}</h3>
            <p class="card-desc">{{ project.desc }}</p>
            <p class="card-info">
              <strong>기간:</strong> {{ project.period }}
            </p>
            <p class="card-info">
              <strong>기술:</strong> {{ project.tech }}
            </p>
          </div>
        </div>
      </div>
    </div>
  </section>
</template>

<script>
import { ref, onMounted, onBeforeUnmount } from "vue";

export default {
  name: "MyProjects",
  setup() {
    const sectionRef = ref(null);
    let observer = null;

    const projects = [
      {
        title: "도파민 대신 해파리 키우기",
        image: require("@/assets/projects/project1.png"),
        period: "2024-09 ~ 2024-12",
        tech: "Jsp, Java backend, MySQL",
        desc: "하루에 남는 잉여시간을 효율적으로 활용할 수 있게 도와주는 웹 페이지입니다.",
      },
      {
        title: "TripPlan 여행 어플",
        image: require("@/assets/projects/project2.png"),
        period: "2025-03 ~ 2025-06",
        tech: "Android(Java), Firebase, Google Maps API, Open Ai API",
        desc: "여행 일정 생성 및 지역 추천 기능을 가진 안드로이드 앱입니다.",
      },
      {
        title: "사이버 일기",
        image: require("@/assets/projects/project3.png"),
        period: "2024-11 ~ 2024-12",
        tech: "Java Swing, MySQL",
        desc: "회원가입/로그인 기능을 가진 다이어리 데스크탑 프로그램입니다.",
      },
      {
        title: "취향 포켓몬 찾기",
        image: require("@/assets/projects/project4.png"),
        period: "2024-11 ~ 2024-12",
        tech: "Jsp, MySQL",
        desc: "사용자 입력 기반으로 포켓몬을 추천하는 간단한 웹 페이지입니다.",
      },
    ];

    onMounted(() => {
      observer = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (entry.isIntersecting) {
              entry.target.classList.add("visible");
            } else {
              entry.target.classList.remove("visible");
            }
          });
        },
        {
          threshold: 0.1,
          rootMargin: "0px 0px -100px 0px",
        }
      );

      if (sectionRef.value) {
        observer.observe(sectionRef.value);
      }
    });

    onBeforeUnmount(() => {
      if (observer && sectionRef.value) {
        observer.unobserve(sectionRef.value);
      }
    });

    return {
      sectionRef,
      projects,
    };
  },
};
</script>

<style scoped>
.projects-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 30px;
  margin-top: 30px;
}

.project-card {
  aspect-ratio: 1;
  width: 100%;
  border: 2px solid #000;
  border-radius: 8px;
  perspective: 1000px;
  cursor: pointer;
  background: #fff;
  overflow: hidden;
}

.card-inner {
  width: 100%;
  height: 100%;
  transition: transform 0.6s ease;
  transform-style: preserve-3d;
  position: relative;
}

.project-card:hover .card-inner {
  transform: rotateY(180deg);
}

.card-front,
.card-back {
  position: absolute;
  width: 100%;
  height: 100%;
  backface-visibility: hidden;
}

.card-front {
  display: flex;
  justify-content: center;
  align-items: center;
  background: #f8f8f8;
}

.project-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.card-back {
  padding: 20px;
  background: #ffffff;
  border: 2px solid #000;
  transform: rotateY(180deg);
  text-align: left;
  display: flex;
  flex-direction: column;
  gap: 8px;
  overflow-y: auto;
}

.card-title {
  font-size: 1.2rem;
  font-weight: 700;
  margin: 0 0 10px 0;
  color: #000;
}

.card-desc {
  font-size: 0.95rem;
  line-height: 1.5;
  margin: 0 0 10px 0;
  color: #333;
}

.card-info {
  font-size: 0.9rem;
  margin: 0;
  color: #555;
}

.card-info strong {
  color: #000;
}

@media (max-width: 768px) {
  .projects-grid {
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 20px;
  }

  .card-title {
    font-size: 1.1rem;
  }

  .card-desc,
  .card-info {
    font-size: 0.85rem;
  }

  .card-back {
    padding: 15px;
  }
}
</style>