<template>
  <section id="skills" class="section" ref="sectionRef">
    <h2 class="section-title">Skills</h2>
    <div class="skills-wrap">
      <div
        v-for="group in skillGroups"
        :key="group.title"
        class="skill-group"
      >
        <div class="group-title">
          <span class="group-icon">{{ group.icon }}</span>
          <h3>{{ group.title }}</h3>
        </div>
        <div class="tags">
          <span
            v-for="tag in group.items"
            :key="tag"
            class="tag"
          >
            {{ tag }}
          </span>
        </div>
      </div>
    </div>
  </section>
</template>

<script>
import { ref, onMounted, onBeforeUnmount } from "vue";

export default {
  name: "MySkills",
  setup() {
    const sectionRef = ref(null);
    let observer = null;

    const skillGroups = [
      {
        title: "Language",
        icon: "💬",
        items: ["Java", "JavaScript", "Python", "C", "C#", "SQL", "Go"],
      },
      {
        title: "Frontend",
        icon: "🎨",
        items: ["HTML5", "CSS3", "Vue.js", "Bootstrap"],
      },
      {
        title: "Backend / DB",
        icon: "🧩",
        items: ["PHP", "MySQL", "Firebase"],
      },
      {
        title: "Mobile",
        icon: "📱",
        items: ["Android (Java)"],
      },
      {
        title: "Tools",
        icon: "🛠️",
        items: [
          "Git / GitHub",
          "Android Studio",
          "VS Code",
          "VS",
          "Eclipse",
          "NetBeans",
        ],
      },
    ];

    onMounted(() => {
      observer = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (entry.isIntersecting) {
              entry.target.classList.add("visible");
            }
          });
        },
        {
          threshold: 0.1,
          rootMargin: "0px 0px -100px 0px",
        }
      );

      if (sectionRef.value) {
        observer.observe(sectionRef.value);
      }
    });

    onBeforeUnmount(() => {
      if (observer && sectionRef.value) {
        observer.unobserve(sectionRef.value);
      }
    });

    return {
      sectionRef,
      skillGroups,
    };
  },
};
</script>

<style scoped>
.skills-wrap {
  display: flex;
  flex-direction: column;
  gap: 35px;
  margin-top: 25px;
}

.skill-group .group-title {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}

.group-icon {
  font-size: 1.4rem;
}

.skill-group h3 {
  font-size: 1.2rem;
  font-weight: 700;
  margin: 0;
}

.tags {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.tag {
  display: inline-block;
  padding: 8px 14px;
  border: 2px solid #000;
  border-radius: 999px;
  font-size: 0.95rem;
  font-weight: 600;
  background: #fff;
  color: #000;
  transition: transform 0.2s ease, background 0.2s ease, color 0.2s ease;
  cursor: default;
}

.tag:hover {
  transform: translateY(-2px);
  background: #000;
  color: #fff;
}

@media (max-width: 768px) {
  .tag {
    font-size: 0.9rem;
    padding: 7px 12px;
  }
}
</style>